BEGIN READ ONLY; SELECT c."Slug",d."DocumentNumber",jsonb_array_length(d."SnapshotJson"::jsonb->'assets') AS asset_count,d."SnapshotJson"::jsonb->'assets'->0->>'assetTag' AS asset_tag,e."CompanyId"=d."CompanyId" AS employee_scoped,d."RecipientSignedAt" IS NOT NULL AS recipient_signed,d."IssuerSignedAt" IS NOT NULL AS issuer_signed FROM "EmployeeHandoverDocuments" d JOIN "Companies" c ON c."Id"=d."CompanyId" JOIN "Employees" e ON e."Id"=d."EmployeeId" WHERE d."DocumentNumber"='ZMB-20261025-a11cc2306'; COMMIT;
